//! 🌱️ Literal Generation cluster fields under the caller's native ownership control.
use semio_framework_artifact_flow_flow::{FlowUi,FlowNodeGui,FlowPreviewGui,FlowChannelRef,CameraJson,WidgetLayout,NodeChrome,OrderedMap,OrderedSet,neural::{Tree,Neuron,Synapse,Dictionary,ColdOwner}};
use semio_framework_value::{DslValue,FromValue,ToValue,NativeDecodeControl,NativeEncodeControl,ValueError,ValueRefusalKind};
use semio_framework_value::ordered::{Grant,RetirementStep};
type Result<T> = std::result::Result<T,ValueError>;
struct ValueOwner(Option<DslValue>);
impl ValueOwner{fn take(mut self)->DslValue{self.0.take().unwrap()}}
impl Drop for ValueOwner{fn drop(&mut self){if let Some(v)=self.0.take(){<DslValue as FromValue>::retire_decoded(v)}}}
fn object(count:usize,c:&mut NativeEncodeControl<'_>)->Result<ValueOwner>{Ok(ValueOwner(Some(DslValue::Object(c.allocate_vec(count)?))))}
fn add(v:&mut ValueOwner,name:&str,value:DslValue,c:&mut NativeEncodeControl<'_>)->Result<()>{let value=ValueOwner(Some(value));let name=c.copy_text(name)?;if let Some(DslValue::Object(fields))=&mut v.0{fields.push((name,value.take()));}else{return Err(ValueError::new(ValueRefusalKind::InvariantViolated, "Generation object owner differs"))}Ok(())}
fn field<'a>(v:&'a DslValue,key:&str)->Result<&'a DslValue>{let DslValue::Object(fields)=v else{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation cluster object differs"))};let mut found=fields.iter().filter(|(k,_)|k==key);let v=&found.next().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,format!("Generation field {key} missing")))?.1;if found.next().is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation duplicate field"))}Ok(v)}
fn read<T:FromValue>(v:&DslValue,c:&mut NativeDecodeControl<'_>)->Result<T>{c.scoped_stage(|c|{c.begin_stage(0)?;T::from_value_controlled(v,c)})}
fn write<T:ToValue>(v:&T,c:&mut NativeEncodeControl<'_>)->Result<DslValue>{c.scoped_stage(|c|{c.begin_stage(0)?;v.to_value_controlled(c)})}
fn list(v:&DslValue)->Result<&[DslValue]>{if let DslValue::Array(items)=v{Ok(items)}else{Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation array differs"))}}
fn pairs(v:&DslValue)->Result<&[(String,DslValue)]>{if let DslValue::Object(items)=v{Ok(items)}else{Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation map differs"))}}
pub(super) fn tree_encode(t:&Tree,c:&mut NativeEncodeControl<'_>)->Result<DslValue>{c.scoped_depth(64,|c|c.scoped_stage(|c|{c.begin_stage(t.neurons.len()+t.synapses.len())?;let mut out=object(2,c)?;let mut neurons=ValueOwner(Some(DslValue::Array(c.allocate_vec(t.neurons.len())?)));for n in &t.neurons{let mut v=object(4,c)?;add(&mut v,"id",write(&n.id,c)?,c)?;add(&mut v,"kind",write(&n.kind,c)?,c)?;add(&mut v,"params",write(&n.params,c)?,c)?;let child=if let Some(child)=&n.tree{c.scoped_stage(|c|tree_encode(child,c))?}else{DslValue::Null};add(&mut v,"tree",child,c)?;if let Some(DslValue::Array(items))=&mut neurons.0{items.push(v.take());}c.step()?;}add(&mut out,"neurons",neurons.take(),c)?;let mut synapses=ValueOwner(Some(DslValue::Array(c.allocate_vec(t.synapses.len())?)));for s in &t.synapses{let mut v=object(5,c)?;add(&mut v,"id",write(&s.id,c)?,c)?;add(&mut v,"from",write(&s.from,c)?,c)?;add(&mut v,"to",write(&s.to,c)?,c)?;add(&mut v,"fromPort",write(&s.from_port,c)?,c)?;add(&mut v,"toPort",write(&s.to_port,c)?,c)?;if let Some(DslValue::Array(items))=&mut synapses.0{items.push(v.take());}c.step()?;}add(&mut out,"synapses",synapses.take(),c)?;Ok(out.take())}))}
pub(super) fn tree_decode(v:&DslValue,c:&mut NativeDecodeControl<'_>)->Result<Tree>{c.scoped_depth(64,|c|c.scoped_stage(|c|{let neurons=list(field(v,"neurons")?)?;let synapses=list(field(v,"synapses")?)?;c.begin_stage(neurons.len()+synapses.len())?;let mut out=ColdOwner::new(Tree{neurons:c.allocate_vec(neurons.len())?,synapses:c.allocate_vec(synapses.len())?});for n in neurons{let id=read(field(n,"id")?,c)?;let kind=read(field(n,"kind")?,c)?;let params=ColdOwner::new(read::<Dictionary>(field(n,"params")?,c)?);let child=field(n,"tree")?;let tree=if matches!(child,DslValue::Null){None}else{let tree=ColdOwner::new(c.scoped_stage(|c|tree_decode(child,c))?);c.charge(std::mem::size_of::<Tree>())?;Some(Box::new(tree.into_inner()))};out.neurons.push(Neuron{id,kind,params:params.into_inner(),tree});c.step()?;}for s in synapses{out.synapses.push(Synapse{id:read(field(s,"id")?,c)?,from:read(field(s,"from")?,c)?,to:read(field(s,"to")?,c)?,from_port:read(field(s,"fromPort")?,c)?,to_port:read(field(s,"toPort")?,c)?});c.step()?;}Ok(out.into_inner())}))}
struct MapOwner<V>(Option<OrderedMap<V>>);
impl<V> MapOwner<V>{fn take(mut self)->OrderedMap<V>{self.0.take().unwrap()}}
fn retire_map<V>(v:OrderedMap<V>){let mut r=v.retire();loop{let maximum_bytes=r.next_close_byte_demand().expect("finite Generation map demand").max(1);match r.advance(Grant{maximum_items:1,maximum_bytes}){RetirementStep::Complete=>break,RetirementStep::OwnedValue(v)=>drop(v),_=>{}}}}
impl<V> Drop for MapOwner<V>{fn drop(&mut self){if let Some(v)=self.0.take(){retire_map(v)}}}
pub(super) fn insert<V>(map:&mut OrderedMap<V>,key:String,value:V,c:&mut NativeDecodeControl<'_>)->Result<()>{c.charge(std::mem::size_of::<String>()+std::mem::size_of::<V>()+4*std::mem::size_of::<usize>())?;let mut cursor=map.begin_set(key,value);let result=(||{while !cursor.is_complete(){c.checkpoint()?;cursor.advance_insert_controlled(Grant{maximum_items:1,maximum_bytes:4096},c)?;}let next=cursor.take_result().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated, "Generation controlled map result missing"))?;retire_map(std::mem::replace(map,next));Ok(())})();cursor.begin_close();loop{match cursor.close_step(Grant{maximum_items:1,maximum_bytes:4096}){RetirementStep::Complete=>break,RetirementStep::OwnedValue(v)=>drop(v),_=>{}}}result}
fn set_encode(v:&OrderedSet,c:&mut NativeEncodeControl<'_>)->Result<DslValue>{c.scoped_stage(|c|{c.begin_stage(v.len())?;let mut items=c.allocate_vec(v.len())?;for s in v.iter(){items.push(write(s,c)?);c.step()?;}Ok(DslValue::Array(items))})}
pub(super) fn set_decode(v:&[String],c:&mut NativeDecodeControl<'_>)->Result<OrderedSet>{c.scoped_stage(|c|{c.begin_stage(v.len())?;let mut out=MapOwner(Some(OrderedMap::new()));for s in v{let key=c.copy_text(s)?;insert(out.0.as_mut().unwrap(),key,(),c)?;c.step()?;}Ok(OrderedSet::from_map(out.take()))})}
struct GuiOwner(Option<FlowUi>);
impl GuiOwner{fn take(mut self)->FlowUi{self.0.take().unwrap()}}
impl Drop for GuiOwner{fn drop(&mut self){if let Some(v)=self.0.take(){v.retire_cold()}}}
pub(super) fn gui_encode(v:&FlowUi,c:&mut NativeEncodeControl<'_>)->Result<DslValue>{c.scoped_stage(|c|{c.begin_stage(v.nodes.len()+v.previews.len())?;let mut out=object(3,c)?;add(&mut out,"camera",write(&v.camera,c)?,c)?;let mut nodes=object(v.nodes.len(),c)?;for(k,n)in v.nodes.iter(){add(&mut nodes,k,write(n,c)?,c)?;c.step()?;}add(&mut out,"nodes",nodes.take(),c)?;let mut previews=ValueOwner(Some(DslValue::Array(c.allocate_vec(v.previews.len())?)));for p in &v.previews{let mut item=object(6,c)?;add(&mut item,"id",write(&p.id,c)?,c)?;add(&mut item,"source",write(&p.source,c)?,c)?;add(&mut item,"mode",write(&p.mode,c)?,c)?;add(&mut item,"preview",write(&p.preview,c)?,c)?;add(&mut item,"expanded",set_encode(&p.expanded,c)?,c)?;add(&mut item,"layout",write(&p.layout,c)?,c)?;if let Some(DslValue::Array(items))=&mut previews.0{items.push(item.take());}c.step()?;}add(&mut out,"previews",previews.take(),c)?;Ok(out.take())})}
pub(super) fn gui_decode(v:&DslValue,c:&mut NativeDecodeControl<'_>)->Result<FlowUi>{c.scoped_stage(|c|{let nodes=pairs(field(v,"nodes")?)?;let previews=list(field(v,"previews")?)?;c.begin_stage(nodes.len()+previews.len())?;let mut out=GuiOwner(Some(FlowUi{camera:read::<CameraJson>(field(v,"camera")?,c)?,nodes:OrderedMap::new(),previews:c.allocate_vec(previews.len())?}));for(k,n)in nodes{let key=c.copy_text(k)?;let node=read::<FlowNodeGui>(n,c)?;insert(&mut out.0.as_mut().unwrap().nodes,key,node,c)?;c.step()?;}for p in previews{let id=read(field(p,"id")?,c)?;let source=read::<Option<FlowChannelRef>>(field(p,"source")?,c)?;let mode=read(field(p,"mode")?,c)?;let preview=ColdOwner::new(read::<Dictionary>(field(p,"preview")?,c)?);let expanded=read::<Vec<String>>(field(p,"expanded")?,c)?;let set=MapOwner(Some(OrderedMap::new()));let mut set=set;c.scoped_stage(|c|{c.begin_stage(expanded.len())?;for key in expanded{insert(set.0.as_mut().unwrap(),key,(),c)?;c.step()?;}Ok::<_,ValueError>(())})?;let layout=read::<Option<WidgetLayout>>(field(p,"layout")?,c)?;out.0.as_mut().unwrap().previews.push(FlowPreviewGui{id,source,mode,preview:preview.into_inner(),expanded:OrderedSet::from_map(set.take()),layout});c.step()?;}Ok(out.take())})}

pub(super) fn playbook_decode(values:std::collections::BTreeMap<String,DslValue>,c:&mut NativeDecodeControl<'_>)->Result<semio_framework_artifact_playbook_playbook::PlaybookValues>{let mut entries=c.allocate_vec(values.len())?;c.scoped_stage(|c|{c.begin_stage(values.len())?;for value in values{entries.push(value);c.step()?;}Ok::<_,ValueError>(())})?;let values=ValueOwner(Some(DslValue::Object(entries)));read(values.0.as_ref().unwrap(),c)}
pub(super) fn playbook_encode(values:&semio_framework_artifact_playbook_playbook::PlaybookValues,c:&mut NativeEncodeControl<'_>)->Result<semio_framework_dsl_record::FieldValue>{
 c.scoped_stage(|c|{use semio_framework_dsl_record::DslField;
use semio_framework_dsl_record::FieldValue;let mut output=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(c.allocate_vec(values.len())?,|items:Vec<(String,FieldValue)>|for(_,v)in items{semio_framework_dsl_record::native_encoding::retire_field(v)});c.begin_stage(values.len())?;for(key,value)in values{let key=c.copy_text(key)?;let value=c.scoped_stage(|c|{c.begin_stage(0)?;semio_framework_dsl_record::DslField::to_value_controlled(value,c)})?;output.as_mut().push((key,value));c.step()?;}Ok(semio_framework_dsl_record::FieldValue::Map(output.take()))})
}
